pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // 1. Tighten domain: arrays must have same length > 0, and all _tos entries must be distinct from caddress to avoid self-call
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != caddress);
            vm.assume(from != _tos[i]);
        }

        // 2. Deploy a helper that always succeeds on transferFrom and return true
        Helper successHelper = new Helper(true);

        // 3. Drive c's transfer using the helper as the external callee
        bool ret = c.transfer(from, address(successHelper), _tos, v);

        // 4. Assert the general rule: the return value must be true
        assertTrue(ret);
    }
}

contract Helper {
    bool private _success;
    constructor(bool success_) { _success = success_; }
    function transferFrom(address, address, uint256) external view returns (bool) {
        return _success;
    }
}

