pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(0));
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool returned) {
            success = true;
            require(returned, "returned false in reference");
        } catch {
            success = false;
        }
        assertTrue(success ? true : true);
        // The reference returns true on every non-reverting path; the bug returns false.
        // A non-reverting execution must yield true. The bug breaks this.
        if (success) {
            bytes memory cd = abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v);
            (bool s, bytes memory d) = address(c).call(cd);
            bool refOk = s && abi.decode(d, (bool));
            assertTrue(refOk);
        }
    }
}

