pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // Admissible domain: avoid arithmetic revert in encoding loop due to array length mismatch
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);

        // Ensure the low-level call to caddress does not revert for any element, so the reference and mutant both reach the final return.
        // Since fuzzed addresses are EOAs with no code, calls to them succeed and return true.
        // We must deploy a helper that also succeeds on transferFrom to observe the correct rule,
        // but the core property is that if the call completes without reverting, the return value is strictly true.
        // However, the bug manifests in the return value independent of callee behavior, as long as the transaction does not revert.
        // If any internal call reverts, both P and M revert, so no return difference is observed.
        // Therefore we must guarantee internal calls succeed. We achieve this by deploying a trivial always-success callee.
        // This helper represents a standard ERC20 that always returns true for transferFrom.
        Helper helper = new Helper();
        for (uint i = 0; i < _tos.length; i++) {
            _tos[i] = address(helper);
        }
        caddress = address(helper);
        // fuzz them again to satisfy same-length assumption, but reassign to helper to ensure success.
        // We keep original fuzzed params but override the actual callee address with the helper.
        // This is necessary because a raw address parameter is an EOA and calls to it succeed,
        // but we need to guarantee it does not revert to observe the return value difference.
        // The adversarial counterparty here is that the original C expects any external party and returns true always;
        // the mutant changes return logic. The helper ensures we can observe the return.

        // Execute transfer
        bool ret = c.transfer(from, address(helper), _tos, v);

        // Property: If transfer did not revert (we reached this point), the returned value must be true.
        // The reference always returns true; the mutant returns _tos.length == 0, which is false because _tos.length > 0.
        assertTrue(ret);
    }
}

contract Helper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
